import json
from copy import deepcopy

def solve_zebra_puzzle():
    # Input variables derived from the puzzle
    houses = [1, 2]  # numbered 1 to 2 from left to right
    categories = ["name", "favorite sports", "hobby"]
    values = {
        "name": ["Eric", "Arnold"],
        "favorite sports": ["basketball", "soccer"],
        "hobby": ["photography", "gardening"]
    }

    # Constraints from clues:
    # 1. The person who enjoys gardening is Arnold.
    equivalences = [
        (("hobby", "gardening"), ("name", "Arnold"))
    ]

    # 2. The photography enthusiast is not in the first house.
    # 3. The person who loves soccer is not in the first house.
    not_allowed = {
        (1, "hobby"): {"photography"},
        (1, "favorite sports"): {"soccer"}
    }

    # Build variables: one variable per (house, category)
    variables = [(h, c) for h in houses for c in categories]

    # Initial domains for each variable
    domains = {}
    for var in variables:
        h, c = var
        dom = set(values[c])
        if (h, c) in not_allowed:
            dom = dom - not_allowed[(h, c)]
        domains[var] = dom

    def is_consistent(assign, var, val):
        h, c = var

        # House-specific not allowed
        if (h, c) in not_allowed and val in not_allowed[(h, c)]:
            return False

        # Uniqueness: values in same category must be unique across houses
        for (oh, oc), oval in assign.items():
            if oc == c and oval == val and oh != h:
                return False

        # Apply equivalence constraints
        #  - the pair ((c1, v1), (c2, v2)) must be in the same house
        # Check for any immediate contradictions
        for (c1v1, c2v2) in equivalences:
            (c1, v1) = c1v1
            (c2, v2) = c2v2

            # Helper to find house of a specific (category, value) in current assignment (including proposed assignment)
            def house_of(cat, value):
                # check assigned variables
                for (ah, ac), aval in assign.items():
                    if ac == cat and aval == value:
                        return ah
                # also consider the current proposed assignment
                if c == cat and val == value:
                    return h
                return None

            h1 = house_of(c1, v1)
            h2 = house_of(c2, v2)

            # If both sides are assigned to different houses, inconsistent
            if h1 is not None and h2 is not None and h1 != h2:
                return False

            # If at some house, one side is assigned, ensure the other side (if assigned at that house) matches
            for hh in houses:
                # At house hh, if c1=v1 then c2 must be v2 (if assigned)
                c1_assigned_here = ((hh, c1) in assign and assign[(hh, c1)] == v1) or (hh == h and c == c1 and val == v1)
                if c1_assigned_here:
                    if (hh, c2) in assign and assign[(hh, c2)] != v2:
                        return False
                # Conversely, if c2=v2 then c1 must be v1 (if assigned)
                c2_assigned_here = ((hh, c2) in assign and assign[(hh, c2)] == v2) or (hh == h and c == c2 and val == v2)
                if c2_assigned_here:
                    if (hh, c1) in assign and assign[(hh, c1)] != v1:
                        return False

        return True

    def select_unassigned_variable(assign, domains):
        # MRV heuristic: choose variable with the smallest remaining domain
        unassigned = [v for v in variables if v not in assign]
        # For dynamic domain filtering, compute current feasible values
        def current_domain(v):
            h, c = v
            dom = set(domains[v])
            # enforce uniqueness by removing already used values in same category
            used = {aval for (ah, ac), aval in assign.items() if ac == c}
            dom -= used
            return dom
        unassigned.sort(key=lambda v: len(current_domain(v)))
        return unassigned[0] if unassigned else None

    def backtrack(assign, domains):
        if len(assign) == len(variables):
            return assign

        var = select_unassigned_variable(assign, domains)
        if var is None:
            return None

        # Compute dynamic domain considering current assignment for uniqueness
        h, c = var
        dynamic_domain = list(set(domains[var]) - {aval for (ah, ac), aval in assign.items() if ac == c})
        # Order values to try (no special heuristic needed for small problem)
        for val in dynamic_domain:
            if is_consistent(assign, var, val):
                assign[var] = val

                # Forward checking: reduce domains based on assignment
                saved_domains = deepcopy(domains)
                # Enforce uniqueness in category c
                for (vh, vc) in domains:
                    if vc == c and (vh, vc) not in assign:
                        if val in domains[(vh, vc)]:
                            domains[(vh, vc)].discard(val)

                # Enforce equivalences minimally in domains
                for (c1v1, c2v2) in equivalences:
                    (c1, v1) = c1v1
                    (c2, v2) = c2v2
                    # If we just assigned c1=v1 at house h, ensure at house h domain for c2 is {v2} where possible
                    if c == c1 and val == v1:
                        # remove v2 from all other houses for c2
                        for hh in houses:
                            if hh != h and (hh, c2) in domains and (hh, c2) not in assign:
                                domains[(hh, c2)].discard(v2)
                        # keep v2 in this house
                        if (h, c2) in domains and (h, c2) not in assign:
                            # If domain doesn't contain v2, this path is impossible
                            if v2 not in domains[(h, c2)]:
                                domains = saved_domains
                                del assign[var]
                                break
                            domains[(h, c2)] = {v2}
                    # Similarly, if we just assigned c2=v2
                    if c == c2 and val == v2:
                        for hh in houses:
                            if hh != h and (hh, c1) in domains and (hh, c1) not in assign:
                                domains[(hh, c1)].discard(v1)
                        if (h, c1) in domains and (h, c1) not in assign:
                            if v1 not in domains[(h, c1)]:
                                domains = saved_domains
                                del assign[var]
                                break
                            domains[(h, c1)] = {v1}
                else:
                    result = backtrack(assign, domains)
                    if result is not None:
                        return result

                # Restore on failure
                domains = saved_domains
                del assign[var]

        return None

    solution_assign = backtrack({}, deepcopy(domains))
    if solution_assign is None:
        raise ValueError("No solution found")

    # Build output
    header = ["House"] + categories
    rows = []
    for h in houses:
        row = [str(h)]
        for c in categories:
            row.append(solution_assign[(h, c)])
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_zebra_puzzle()
    print(json.dumps(result, indent=2))
